#!/usr/bin/env python3
"""Batch-19 wave-1 converter: NHC 健康科普辟谣平台 raw text -> medical KnowledgeEntry JSON.

Reads external/nhc_rumor/raw/*.txt (verbatim WeChat article text harvested by
fetch_nhc_rumor.py) and writes internal/knowledge/data/nhc_rumor_debunk.json.

Why the text goes into `prevention` and not `summary_zh`/`details_zh`: the medical
dataset is unmarshalled into knowledge.KnowledgeEntry, which has NO title_zh /
summary_zh / details_zh fields (see internal/knowledge/schemas.go) — keys with those
names are silently dropped at seed time, so an article body stored under them would
never reach retrieval scoring (retriever_keyword.go scores ConditionZH +
clinical/risk/complication/differential/prevention) nor the prompt
(knowledge_search.go emits prevention / when_to_seek_care).

Authoring rules encoded here:
  * one entry per MYTH, not per article — CURATED groups several raw files into one
    entry and keeps one citation per source, because 同一谣言被不同日期重复发布
    would otherwise compete with itself for the same top5 slot.
  * condition_zh is a SHORT topical phrase (no 什么时候/怎么办/是不是 frames, no bare
    digit token) so rule 3 (bidirectional whole-string containment, +5.0) fires.
  * body paragraphs are copied verbatim from the raw file after a fixed junk-line
    strip list (WeChat UI + 出品/审核 credits); numbers are never rewritten.
  * citation.title is always set (a citation missing title is a verify-knowledge
    ERROR), journal stays empty (institutional 科普 has no DOI/PMID by design).

Usage:
    python3 external/nhc_rumor/convert_nhc_rumor.py
"""
import glob
import json
import os
import re
import sys

RAW_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "raw")
OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
                   "internal", "knowledge", "data", "nhc_rumor_debunk.json")

# Lines that are WeChat UI chrome or production credits, never answer content.
JUNK = [
    r"^点击查看所?in?全文?$", r"^点击查看更多$", r"^[▼▲△✖✔×]$",
    r"^是真是假弄不清[？?]$", r"^评论区私我.*$", r"^辟谣$", r"^谣言终结站$",
    r"^硬核打假.*$", r"^不听\s*不信\s*不传谣$", r"^关注合集.*$",
    r"^多学一个知识点$", r"^本文配图来源于版权图库.*$", r"^转载时请注意.*$",
    r"^\s*$",
]
CREDIT_RE = re.compile(r"^(出品|审核|来源|策划|制图|编辑|校对|记者|通讯员|作者|供稿)[：:]")
HEADING_RE = re.compile(r"^——.+")
# Photo caption lines start with △ + the photographer/institution name; ▲ is the
# site's bullet marker for real advice and must stay. Image-source disclaimers vary
# in wording ("本文部分配图…"), so match on the substring rather than an anchor.
CAPTION_RE = re.compile(r"^△")
IMAGE_RIGHTS_RE = re.compile(r"来源于版权图库")

CITATION_BASE = "健康科普辟谣平台·谣言终结站（国家卫生健康委官网）- "


def parse(path):
    lines = open(path, encoding="utf-8").read().splitlines()
    head = {}
    for l in lines[:6]:
        if l.startswith("# "):
            k, _, v = l[2:].partition(":")
            head[k.strip()] = v.strip()
    body = lines[6:] if lines and lines[0].startswith("#") else lines
    paras, credits = [], []
    for l in body:
        s = l.strip()
        if not s:
            continue
        if any(re.match(p, s) for p in JUNK):
            continue
        if CREDIT_RE.match(s):
            credits.append(s)
            continue
        if HEADING_RE.match(s) or CAPTION_RE.match(s) or IMAGE_RIGHTS_RE.search(s):
            continue
        paras.append(s)
    return head, paras, credits


def cjk(s):
    return len(re.findall(r"[\u4e00-\u9fff]", s))


def myth_core(title):
    """The rumor statement itself, without the 是真是假/合集 suffix or the 提醒 prefix."""
    t = re.split(r"[|｜]\s*谣言终结站|全国肿瘤防治宣传周", title)[0]
    t = re.split(r"是真是假", t)[0]
    t = re.sub(r"^国家卫生健康委提醒[：:]\s*", "", t)
    t = t.strip("……？?！! 。、")
    return t


