def normq(s):
    """Curly/straight quote agnostic matching — the pages use “ ”, the table uses \"."""
    return s.replace("“", '"').replace("”", '"').replace("‘", "'").replace("’", "'")


def build():
    files = sorted(glob.glob(os.path.join(RAW_DIR, "*.txt")))
    parsed = []
    for p in files:
        head, paras, credits = parse(p)
        parsed.append((head.get("标题", ""), head, paras, credits, p))
    by_title = {t: (h, ps, cr, p) for t, h, ps, cr, p in parsed}

    used, entries = set(), []
    for cond, hooks, extra in CURATED:
        sources = []
        for hk in hooks:
            matches = [t for t in by_title if normq(hk) in normq(t)]
            if len(matches) != 1:
                sys.exit("hook %-30s matched %d titles (need exactly 1)" % (hk, len(matches)))
            t = matches[0]
            if t in used:
                sys.exit("title used twice: %s" % t)
            used.add(t)
            sources.append(t)
        body = []
        cites = []
        for t in sources:
            head, paras, credits, path = by_title[t]
            keep = [x for x in paras if cjk(x) >= 20]
            if not keep:
                sys.exit("no body paragraph for %s" % t)
            body.extend(keep)
            prov = "；".join(credits) if credits else ""
            cites.append({
                "type": "national_guideline",
                "title": CITATION_BASE + t + (("（" + prov + "）") if prov else ""),
                "journal": "",
                "year": int(re.search(r"(20\d{2})", head.get("发布日期", "2025")).group(1)),
                "doi": "",
                "pmid": "",
                "level": "official_guideline",
                "url": head.get("URL", ""),
            })
        slug = re.sub(r"[^0-9A-Za-z一-鿿]+", "", cond)[:10]
        kws = [cond] + extra + [myth_core(t) for t in sources]
        # dedupe preserving order
        seen, keywords = set(), []
        for k in kws:
            k = k.strip()
            if k and k not in seen:
                seen.add(k)
                keywords.append(k)
        entries.append({
            "id": "nr-" + slug,
            "condition_zh": cond,
            "condition_en": "",
            "category": "rumor_debunking",
            "keywords": keywords,
            "prevention": body,
            "citations": cites,
        })

    unused = [t for t in by_title if t not in used]
    for t in unused:
        print("UNCURATED: %s" % t)
    print("entries: %d | raw files: %d | curated coverage: %d/%d"
          % (len(entries), len(files), len(used), len(files)))
    ids = [e["id"] for e in entries]
    dupes = {i for i in ids if ids.count(i) > 1}
    if dupes:
        sys.exit("duplicate ids: %s" % dupes)
    if unused:
        sys.exit("refusing to write: %d titles lack curation" % len(unused))

    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(entries, f, ensure_ascii=False, indent=2)
        f.write("\n")
    print("wrote %s" % OUT)


if __name__ == "__main__":
    build()
